// Per marked embedding test each side; no assumption that separate successes glue.
use std::io::{self,BufRead};
fn choose(l:&[Vec<usize>],s:&[u32],idx:usize,sel:&mut Vec<u32>,bad:&[Vec<u32>])->bool{if idx==4{return true}for &h in &l[idx]{let r=s[h];let mut ok=true;for sub in 0..(1usize<<idx){let n=sub.count_ones()+1;if n<2{continue}let mut u=r;for j in 0..idx{if (sub>>j)&1==1{u|=sel[j]}}if bad[(8-n)as usize].iter().any(|&q|u&q==0){ok=false;break}}if ok{sel.push(r);if choose(l,s,idx+1,sel,bad){return true}sel.pop();}}false}
struct Run{a:Vec<u32>,b:Vec<u32>,p:Vec<usize>,gr:[u32;2],qs:Vec<Vec<u32>>,sets:std::collections::HashSet<u32>,ct:[usize;3]}
impl Run{fn go(&mut self,ls:&mut Vec<usize>,mask:u32){let j=ls.len();if j<5{let v=self.p[j];let pm=self.p.iter().fold(0,|x,&i|x|(1<<i));for i in 0..21{if mask>>i&1!=0||self.a[i].count_ones()!=4+(self.b[v]&pm).count_ones(){continue}if (0..j).any(|k|self.a[i]>>ls[k]&1!=self.b[v]>>self.p[k]&1){continue}ls.push(i);self.go(ls,mask|1<<i);ls.pop();}return}self.ct[0]+=1;for(side,&g)in self.gr.iter().enumerate(){let mut lists=vec![];let mut rows=vec![];for v in 0..13{if g>>v&1==0{continue}let req=(0..5).filter(|&j|self.b[v]>>self.p[j]&1!=0).fold(0,|m,j|m|1<<ls[j]);let mut l=vec![];for &s in &self.qs[3]{if s&mask==0&&self.sets.contains(&(s|req)){l.push(rows.len());rows.push(s|req)}}lists.push(l)}lists.sort_by_key(Vec::len);if !choose(&lists,&rows,0,&mut vec![],&self.qs){break}self.ct[side+1]+=1}}}
fn main(){for l in io::stdin().lock().lines(){let x:Vec<u32>=l.unwrap().split_whitespace().map(|x|x.parse().unwrap()).collect();let a=x[3..24].to_vec();let mut sets=vec![0u32];for i in 0..21{for j in 0..sets.len(){if sets[j]&a[i]==0{sets.push(sets[j]|1<<i)}}}let mut qs=vec![vec![];7];for &s in &sets{qs[s.count_ones() as usize].push(s)}let mut r=Run{a,b:x[24..].to_vec(),p:(0..13).filter(|i|(x[1]|x[2])>>i&1==0).collect(),gr:[x[1],x[2]],qs,sets:sets.into_iter().collect(),ct:[0;3]};r.go(&mut vec![],0);println!("{} {} {} {} {} {}",x[0],x[1],x[2],r.ct[0],r.ct[1],r.ct[2])}}
